{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Levomepromazine, the closest retrieved analogue (Morgan 0.338), shares a tricyclic sulfur-containing ring and dimethylaminoalkyl side chain; its oral systemic availability was 33–74% in patients, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Clomipramine, a tricyclic antidepressant with a dimethylaminopropyl side chain, had absolute oral bioavailability of 36–68% (mean 48%) in healthy volunteers, showing that this basic lipophilic scaffold typically exceeds the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Imipramine, another close tricyclic analogue, gave absolute oral bioavailability of 29–77% in normal subjects, reinforcing moderate oral bioavailability above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Promethazine, which shares the dimethylaminoethyl side chain with the query, had oral bioavailability of 25% in healthy volunteers, still above the 20% threshold despite extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Prothipendyl, a tricyclic analogue with a dimethylaminopropyl side chain, was reported to have low absolute bioavailability after a single oral dose, providing a contradictory example; however, the result is unquantified and from a single-dose study, and the balance of better-characterized analogues supports high.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is diltiazem, a benzothiazepine calcium-channel blocker with a dimethylaminoethyl side chain and acetate ester. Retrieved tricyclic/basic amine analogues with similar scaffolds and side chains consistently show oral bioavailability in the 25–70% range (levomepromazine 33–74%, clomipramine ~48%, imipramine 29–77%, promethazine 25%), all above the 20% threshold. The one unquantified 'low' result (prothipendyl) is outweighed by these direct measurements and by diltiazem's known moderate oral bioavailability. A modified-release formulation would not be expected to reduce the extent of bioavailability below 20%; therefore the prediction is high.",
  "evidence_gaps": [
    "No direct diltiazem bioavailability record is present in the retrieved evidence; all analogues have low Morgan similarity (<0.35).",
    "The modified-release formulation condition is not directly represented in the experimental records.",
    "Prothipendyl's 'low' bioavailability is not quantified, so its threshold relevance is uncertain.",
    "Some records are from patients with disease states or use systemic availability rather than strict absolute bioavailability, adding variability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

